  fnBillPost: async t => { const tx = Store.clone(FT()), b = tx.bills.find(x => x.id === t.dataset.k), vd = tx.vendors.find(x => x.id === b.vendor); if (b.status !== 'Approved') return toast('Bill is not approved.', 'bad'); const split = true; try { const L = [{ gl: b.gl, dr: b.gross }]; if (b.gst) L.push({ gl: '1401', dr: Math.round(b.gst / 2) }, { gl: '1402', dr: b.gst - Math.round(b.gst / 2) }); L.push({ gl: vd.gl || '2102', cr: b.total, party: vd.name }); if (b.tds) L.push({ gl: vd.gl || '2102', dr: b.tds, party: vd.name }, { gl: '2202', cr: b.tds, party: vd.name }); const j = fnJv(tx, { date: b.invoiceDate >= AYS_ISO && fnPeriodOpen(b.invoiceDate) ? b.invoiceDate : PROC_TODAY, vtype: 'BL', type: 'Vendor bill', bid: b.bid, cc: b.cc, project: b.project, narration: `${b.no} ${vd.name} · ${b.invoiceNo} · ${b.desc}`, src: { mod: 'Accounts Payable', kind: 'Vendor bill', id: b.id, no: b.no, route: 'fn_ap' }, lines: L }); b.jv = j.id; } catch (e) { return toast(e.message, 'bad'); } b.status = 'Posted'; fnLog(b, 'Posted to ledger'); await fnSave(tx); audit('Finance', 'Vendor bill posted', { new: `${b.no} · ${INR(b.net)}`, approval: 'Approved', approver: App.user.name }); closeModal(); toast(b.no + ' posted.'); },
