  fnPayForm: t => { const b = FT().bills.find(x => x.id === t.dataset.k), vd = FT().vendors.find(x => x.id === b.vendor) || {}, bal = b.net - b.paid, emergency = t.dataset.e === '1', adv = FT().payments.filter(p => p.vendor === b.vendor && p.advance && p.status === 'Paid').reduce((s, p) => s + p.amount - (p.adjusted || 0), 0); modal(`${emergency ? 'Emergency payment' : 'Pay'} · ${b.no}`, `<div class="kv4"><div><span>Vendor</span><b>${esc(vd.name)}</b></div><div><span>Bank details</span><b class="small">${esc(vd.bank || '')}</b></div><div><span>Balance</span><b>${INR(bal)}</b></div><div><span>Advance available</span><b>${INR(adv)}</b></div></div><div class="form-grid">${pcFld('Payment date', `<input id="py_date" type="date" value="${PROC_TODAY}" max="${PROC_TODAY}">`)}${pcFld('Amount (₹) – partial allowed', `<input id="py_amt" type="number" min="0" value="${bal}">`)}${pcFld('Adjust advance (₹)', `<input id="py_adv" type="number" min="0" max="${adv}" value="0">`)}${pcFld('Mode', pcSel('py_mode', ['Bank transfer', 'Cheque', 'UPI', 'Cash'], 'Bank transfer'))}${pcFld('Bank / cash account', pcSel('py_bank', FM().coa.filter(g => g.cf === 'Cash' && g.active).map(g => [g.code, `${g.code} ${g.name}`]), '1001'))}${pcFld('Reference (UTR / cheque)', '<input id="py_ref">')}${pcFld('Batch', pcSel('py_batch', ['', 'Regular vendors', 'Utilities', 'Rent', 'Salary-related vendors', 'Emergency approved'], b.batch || ''))}</div>${emergency ? '<label class="fld"><span>Emergency override reason (mandatory – recorded with the approver)</span><input id="py_emg"></label>' : ''}<p class="small muted">Payments above ${INR(FM().cfg.paymentCfoAbove)} need CFO approval before release.</p>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="fnPayOk" data-k="${b.id}" data-e="${emergency ? '1' : ''}">${emergency ? 'Approve override & pay' : 'Create payment'}</button>`); },
  fnPayOk: async t => { const tx = Store.clone(FT()), b = tx.bills.find(x => x.id === t.dataset.k), vd = tx.vendors.find(x => x.id === b.vendor), amt = +v('py_amt') || 0, advAdj = +v('py_adv') || 0, ref = (v('py_ref') || '').trim(), emg = t.dataset.e === '1' ? (v('py_emg') || '').trim() : ''; if (!(amt > 0) || !ref) return toast('Enter the amount and reference.', 'bad'); if (amt + advAdj > b.net - b.paid + 0.5) return toast('Amount exceeds the balance.', 'bad'); if (t.dataset.e === '1' && !emg) return toast('Enter the emergency override reason.', 'bad'); if (vd.status !== 'Active') return toast('Vendor is not approved for payment.', 'bad'); const p = { id: 'PY' + Date.now().toString(36), no: fnNo(tx, 'PV', b.bid, v('py_date')), vendor: vd.id, vendorName: vd.name, bid: b.bid, date: v('py_date'), amount: amt, advAdjusted: advAdj, mode: v('py_mode'), bank: v('py_bank'), ref, bills: [{ bill: b.id, no: b.no, amt: amt + advAdj }], batch: v('py_batch'), emergency: emg, overrideBy: emg ? App.user.name : '', status: 'Draft', createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), chain: [], level: 0, log: [] }; fnLog(p, 'Payment voucher created', emg ? 'Emergency override: ' + emg : ''); if (amt > FM().cfg.paymentCfoAbove || !can('fn_ap', 'Approve')) fnSubmit(tx, p, 'Vendor payment', amt); else { p.status = 'Approved'; p.chain = [{ role: 'Finance', label: 'Finance Manager', status: 'Approved', by: App.user.name, at: nowIso(), remark: 'Within limit' }]; p.level = 1; } tx.payments.unshift(p); await fnSave(tx); audit('Finance', 'Payment voucher ' + (p.status === 'Approved' ? 'approved' : 'submitted'), { new: `${p.no} · ${vd.name} · ${INR(amt)}`, reason: emg, approval: p.status }); closeModal(); if (p.status === 'Approved') fnPayDoc(p.id); else toast(p.no + ' submitted for approval.'); },
  fnPayRelease: async t => { const tx = Store.clone(FT()), p = tx.payments.find(x => x.id === t.dataset.k); if (p.status !== 'Approved') return toast('Payment is not approved.', 'bad'); const vd = tx.vendors.find(x => x.id === p.vendor); try { const L = [{ gl: vd.gl || '2102', dr: p.amount + (p.advAdjusted || 0), party: vd.name }, { gl: p.bank, cr: p.amount }]; if (p.advAdjusted) L.push({ gl: '1503', cr: p.advAdjusted, party: vd.name }); const j = fnJv(tx, { date: p.date, vtype: 'PV', type: 'Vendor payment', bid: p.bid, cc: `CC-${p.bid || 'CORP'}-ADM`, narration: `${p.no} to ${vd.name} · ${p.mode} ${p.ref} · ${p.bills.map(b => b.no).join(', ')}${p.emergency ? ' · EMERGENCY: ' + p.emergency : ''}`, src: { mod: 'Accounts Payable', kind: 'Payment voucher', id: p.id, no: p.no, route: 'fn_ap' }, lines: L }); p.jv = j.id; } catch (e) { return toast(e.message, 'bad'); } p.status = 'Paid'; p.releasedBy = App.user.name; p.releasedAt = nowIso(); fnLog(p, 'Released'); p.bills.forEach(x => { const b = tx.bills.find(y => y.id === x.bill); if (!b) return; b.paid += x.amt; b.status = b.paid >= b.net ? 'Paid' : 'Partly paid'; b.scheduled = ''; fnLog(b, 'Paid', `${p.no} · ${INR(x.amt)}`); }); if (p.advAdjusted) { let left = p.advAdjusted; tx.payments.filter(x => x.vendor === p.vendor && x.advance && x.status === 'Paid').forEach(a => { const take = Math.min(left, a.amount - (a.adjusted || 0)); a.adjusted = (a.adjusted || 0) + take; left -= take; }); } await fnSave(tx); audit('Finance', 'Payment released', { new: `${p.no} · ${INR(p.amount)} · ${p.ref}`, approval: 'Released', approver: App.user.name }); closeModal(); toast(p.no + ' released and posted.'); },
  fnPayReverse: t => pcRemark('Reverse payment', 'Reversing journal is posted; the bill reopens. Reason is mandatory.', true, async rem => { const tx = Store.clone(FT()), p = tx.payments.find(x => x.id === t.dataset.k); const j = tx.journal.find(x => x.id === p.jv); if (j && j.recon) return toast('Payment is reconciled with the bank – un-reconcile first.', 'bad'); if (j) fnReverse(tx, j, rem); p.status = 'Reversed'; fnLog(p, 'Reversed', rem); p.bills.forEach(x => { const b = tx.bills.find(y => y.id === x.bill); if (b) { b.paid -= x.amt; b.status = b.paid > 0 ? 'Partly paid' : 'Posted'; fnLog(b, 'Payment reversed', p.no); } }); await fnSave(tx); audit('Finance', 'Payment reversed', { old: p.no, reason: rem, approval: 'Reversed', approver: App.user.name }); closeModal(); }),
